select count(*) as n, md5(string_agg(h, '' order by h)) as h from (select md5(concat_ws(chr(31), "path", "title", "kind", "module", "format", "artifact_url", "docs_id", "tab_name", "rev", "content", "pdf_path", "sha256")) h from public.documents where "path" in ('modules/F1-histories-of-making/research/TASK_26_Object_Types_Density_Variety.md', 'modules/F1-histories-of-making/research/TASK_27_Movements_Civilisations_Treatment_Decision.md', 'modules/F1-histories-of-making/research/VERIFICATION_NOTES.md', 'modules/F1-histories-of-making/review-logs/REVIEW_LOG_lint_2026-09-29.md')) s;